// Problems: a LeetCode-like list of every code task (#problems), a solver page for one task (#problem/<id>)
// and the self-exam on passed lessons (#selftest, run by the exam screen in local mode).
// The list comes from content/problems/<lang>.js (generated by tools/prerender.js): [id, module, lesson index, type, level, title, xp].
// Problems are open to anyone: a visitor without an account gets a guest profile, like the "try a lesson" button.
(function () {
  DJ.problemScreens = function (ui) {
  const { $, $$, esc, S, ICON, LEVELS, go, toast, track, celebrate, topbar } = ui;
  const LANG = { sql: 'SQL', python: 'Python', java: 'Java', cpp: 'C++' };
  const PAGE = 50;
  const pick = a => a[Math.floor(Math.random() * a.length)];
  let list = null;   // rows from DJ.problems, in course order

  function load() {
    if (list) return Promise.resolve(list);
    const lang = (DJ.i18n && DJ.i18n.lang) || 'kk';
    return ui.loadScript(`content/problems/${lang}.js`).then(() => {
      const order = {};
      let k = 0;
      for (const g of DJ.catalog || []) for (const c of g.courses) for (const m of c.mods) if (order[m] == null) order[m] = k++;
      list = (DJ.problems || []).map(([id, mod, li, type, level, title, xp], n) => ({ id, mod, li, type, level, title, xp, n, course: courseOf(mod) }))
        .sort((a, b) => ((order[a.mod] ?? 999) - (order[b.mod] ?? 999)) || a.n - b.n);
      list.forEach((r, i) => { r.no = i + 1; });
      return list;
    });
  }
  function courseOf(mod) { for (const g of DJ.catalog || []) for (const c of g.courses) if (c.mods.includes(mod)) return c; return null; }
  // 'sql-1#p3' → { lesson id, practice?, index }
  const parse = id => { const [lid, n] = id.split('#'); return { lid, pr: n[0] === 'p', i: Number(n.replace('p', '')) }; };
  async function exerciseOf(r) {
    await DJ.loadModule(r.mod);
    const l = DJ.modules[r.mod].lessons[r.li], w = parse(r.id);
    return { lesson: l, ex: ((w.pr ? l.practice : l.exercises) || [])[w.i] };
  }
  const lvl = l => l && LEVELS[l] ? `<span class="lvl lvl-${l}">${LEVELS[l]}</span>` : '';
  const where = r => { const m = DJ.findModule(r.mod); return m ? `${m.code} ${m.title}` : r.course ? r.course.title : ''; };
  const getF = () => { try { return Object.assign({ q: '', course: '', lang: '', level: '', st: '' }, JSON.parse(DJ.util.lsGet('dj.pf') || '{}')); } catch (e) { return { q: '', course: '', lang: '', level: '', st: '' }; } };

  // ================= the list =================
  function viewProblems() {
    $('#app').innerHTML = '<p class="muted" style="padding:40px 0" role="status">Есептер жүктелуде…</p>';
    load().then(draw).catch(() => { $('#app').innerHTML = '<p class="muted" style="padding:40px 0" role="alert">Есептер жүктелмеді. Интернетті тексеріп, бетті жаңартыңыз.</p>'; });
  }
  function draw() {
    if (ui.route.view !== 'problems') return;
    const p = S.progress(), f = getF();
    const solved = r => !!p.done[r.id];
    const by = lv => { const a = list.filter(r => r.level === lv); return `<div class="pstat lvl-${lv}"><b>${a.filter(solved).length}</b><span>/ ${a.length}</span><small>${LEVELS[lv]}</small></div>`; };
    const courses = [...new Map(list.filter(r => r.course).map(r => [r.course.id, r.course])).values()];
    $('#app').innerHTML = `
      <div class="probs">
        <div class="probs-head">
          <div><h1 style="margin:0 0 6px">Есептер</h1><p class="muted" style="margin:0;max-width:60ch">${list.length} есеп: SQL, Python, Java, C++. Кез келгенін ашып, кодты осы жерде жазып, бірден тексеруге болады.</p></div>
          <div class="pstats"><div class="pstat all"><b>${list.filter(solved).length}</b><span>/ ${list.length}</span><small>шешілді</small></div>${by('easy')}${by('medium')}${by('hard')}</div>
        </div>
        <div class="actions" style="margin:12px 0"><button class="btn" id="p-rand">${ICON.bolt} Кездейсоқ есеп</button><button class="btn ghost" data-go="selftest">${ICON.trophy} Өзіңді тексер</button></div>
        <div class="pfilters" role="search">
          <input type="search" id="pf-q" placeholder="Есепті іздеу" aria-label="Есепті іздеу" value="${esc(f.q)}">
          <select id="pf-course" aria-label="Курс"><option value="">Барлық курстар</option>${courses.map(c => `<option value="${esc(c.id)}" ${f.course === c.id ? 'selected' : ''}>${esc(c.title)}</option>`).join('')}</select>
          <select id="pf-level" aria-label="Қиындық"><option value="">Кез келген қиындық</option>${Object.entries(LEVELS).map(([k, v]) => `<option value="${k}" ${f.level === k ? 'selected' : ''}>${v}</option>`).join('')}</select>
          <select id="pf-st" aria-label="Күйі"><option value="">Барлығы</option><option value="todo" ${f.st === 'todo' ? 'selected' : ''}>Шешілмеген</option><option value="done" ${f.st === 'done' ? 'selected' : ''}>Шешілген</option></select>
          <div class="seg" role="group" aria-label="Тіл">${[['', 'Барлығы']].concat(Object.entries(LANG)).map(([k, v]) => `<button data-pl="${k}" aria-pressed="${f.lang === k}">${v}</button>`).join('')}</div>
        </div>
        <div id="p-rows"></div>
      </div>`;
    const rows = () => {
      const q = f.q.trim().toLowerCase();
      return list.filter(r => (!f.course || (r.course && r.course.id === f.course)) && (!f.lang || r.type === f.lang) && (!f.level || r.level === f.level)
        && (!f.st || (f.st === 'done') === solved(r)) && (!q || r.title.toLowerCase().includes(q) || String(r.no) === q));
    };
    let shown = PAGE;
    const table = () => {
      const all = rows(), part = all.slice(0, shown);
      $('#p-rows').innerHTML = all.length ? `<p class="note" style="margin:0 0 6px">${all.length} есеп</p>
        <div class="ptable" role="table" aria-label="Есептер">${part.map(r => `<a class="prow ${solved(r) ? 'done' : ''}" role="row" href="#problem/${encodeURIComponent(r.id)}" data-pid="${esc(r.id)}">
          <span class="pst" role="cell">${solved(r) ? ICON.check.replace('<svg', '<svg aria-label="шешілді"') : ''}</span>
          <span class="pno" role="cell">${r.no}.</span>
          <span class="pti" role="cell"><b>${esc(r.title)}</b><small>${esc(where(r))}</small></span>
          <span class="plang lang-${r.type}" role="cell">${LANG[r.type]}</span>
          <span role="cell">${lvl(r.level)}</span>
          <span class="pxp" role="cell">+${r.xp} XP</span></a>`).join('')}</div>
        ${all.length > shown ? `<div class="actions" style="justify-content:center;margin-top:12px"><button class="btn ghost" id="p-more">Тағы көрсету (${all.length - shown})</button></div>` : ''}`
        : '<p class="muted">Бұл сүзгі бойынша есеп табылмады.</p>';
      $$('[data-pid]').forEach(a => a.onclick = e => { e.preventDefault(); go('problem', { pid: a.dataset.pid }); });
      if ($('#p-more')) $('#p-more').onclick = () => { shown += PAGE; table(); };
    };
    const save = () => { DJ.util.lsSet('dj.pf', JSON.stringify(f)); shown = PAGE; table(); };
    $('#pf-q').oninput = e => { f.q = e.target.value; save(); };
    $('#pf-course').onchange = e => { f.course = e.target.value; save(); };
    $('#pf-level').onchange = e => { f.level = e.target.value; save(); };
    $('#pf-st').onchange = e => { f.st = e.target.value; save(); };
    $$('[data-pl]').forEach(b => b.onclick = () => { f.lang = b.dataset.pl; $$('[data-pl]').forEach(x => x.setAttribute('aria-pressed', String(x === b))); save(); });
    $('#p-rand').onclick = () => { const a = rows().filter(r => !solved(r)); const r = pick(a.length ? a : list); go('problem', { pid: r.id }); };
    table();
  }

  // ================= one problem =================
  let P = null;   // { r, ex, lesson, cm, hints, fails }
  function viewProblem() {
    const pid = ui.route.pid;
    $('#app').innerHTML = '<p class="muted" style="padding:40px 0" role="status">Есеп жүктелуде…</p>';
    Promise.all([load(), ui.loadEditor()]).then(async () => {
      const r = list.find(x => x.id === pid);
      if (!r) { $('#app').innerHTML = '<div class="diag"><div class="card"><p>Мұндай есеп табылмады.</p><div class="actions"><button class="btn" data-go="problems">Есептерге</button></div></div></div>'; return; }
      const { lesson, ex } = await exerciseOf(r);
      if (ui.route.view !== 'problem' || ui.route.pid !== pid) return;
      if (!ex) { $('#app').innerHTML = '<p class="muted" style="padding:40px 0">Есеп жүктелмеді.</p>'; return; }
      P = { r, ex, lesson, cm: null, hints: 0, fails: 0 };
      drawProblem();
    }).catch(() => { $('#app').innerHTML = '<p class="muted" style="padding:40px 0" role="alert">Есеп жүктелмеді. Интернетті тексеріп, қайта көріңіз.</p>'; });
  }
  function drawProblem() {
    const { r, ex, lesson } = P, p = S.progress(), done = !!p.done[r.id];
    const i = list.indexOf(r), prev = list[i - 1], next = list[i + 1];
    const w = parse(r.id);
    const ds = ex.type === 'sql' ? DJ.datasets[ex.dataset || 'shop'] : null;
    const nat = ex.type === 'java' || ex.type === 'cpp';
    const saved = (p.code || {})[r.id];
    $('#app').innerHTML = `
      <div class="crumbs"><button data-go="problems">Есептер</button><span>/</span><span>${r.no}. ${esc(r.title)}</span></div>
      <div class="lesson prob">
        <article class="reading">
          <div class="eyebrow">${LANG[r.type]} · ${esc(where(r))}</div>
          <h1 style="font-size:1.5rem">${r.no}. ${esc(r.title)}</h1>
          <p style="margin:0 0 10px">${lvl(r.level)} <span class="xp-tag">+${r.xp} XP</span> ${done ? '<span class="chip done">Шешілді</span>' : ''}</p>
          <div class="prose">${ex.prompt}</div>
          ${ds && ds.tables ? `<details class="schema" open><summary>Кестелер</summary>${Object.entries(ds.tables).map(([t, c]) => `<div><code>${esc(t)}</code>: ${esc(c)}</div>`).join('')}</details>` : ''}
          <div class="hints" id="hints"></div>
          <div class="actions" style="margin-top:10px">${(ex.hints || []).length ? `<button class="btn ghost" id="hint-btn">Кеңес (${ex.hints.length})</button>` : ''}<span id="sol-slot"></span>
            <button class="btn ghost" data-go="${w.pr ? 'practice' : 'lesson'}" data-mod="${r.mod}" data-li="${r.li}">Тақырып: ${esc(lesson.title)}</button></div>
          <div class="lesson-nav">${prev ? `<button class="btn ghost" data-pnav="${esc(prev.id)}">← Алдыңғы</button>` : '<span></span>'}${next ? `<button class="btn ghost" data-pnav="${esc(next.id)}">Келесі →</button>` : ''}</div>
        </article>
        <aside class="workbench">
          <div class="editor-shell"><div class="editor-bar"><span><span class="dots"><i></i><i></i><i></i></span><span class="lang">${ds ? 'SQL · ' + esc(ds.title) : { python: 'Python 3', java: 'Java', cpp: 'C++' }[ex.type]}</span></span><span>Ctrl+Enter: іске қосу</span></div><div id="cm"></div></div>
          ${nat ? `<label style="display:block;margin-top:10px"><span class="eyebrow">Кіріс (stdin)</span><textarea id="stdin" rows="3" spellcheck="false" class="stdin">${esc(((ex.check || {}).cases || [])[0] ? ex.check.cases[0].stdin || '' : '')}</textarea></label>` : ''}
          <div class="actions"><button class="btn ghost" id="run">${ICON.play.replace('<svg', '<svg style="width:14px;height:14px"')} Іске қосу</button><button class="btn" id="check">${ICON.check.replace('<svg', '<svg style="width:16px;height:16px"')} Тексеру</button><button class="btn ghost" id="reset">Тазалау</button></div>
          <div id="verdict"></div>
          <div class="output" id="out"><p class="muted" style="margin:0">Нәтиже осында шығады.</p></div>
        </aside>
      </div>`;
    $$('[data-pnav]').forEach(b => b.onclick = () => go('problem', { pid: b.dataset.pnav }));
    if ($('#hint-btn')) $('#hint-btn').onclick = showHint;
    const host = $('#cm'), value = saved != null ? saved : ex.starter || '';
    const runIt = () => doRun();
    if (window.CodeMirror) {
      P.cm = CodeMirror(host, { value, mode: { sql: 'text/x-sqlite', python: 'python', java: 'text/x-java', cpp: 'text/x-c++src' }[ex.type], lineNumbers: true, indentUnit: 4,
        matchBrackets: true, autoCloseBrackets: true, lineWrapping: true, viewportMargin: Infinity,
        extraKeys: { 'Ctrl-Enter': runIt, 'Cmd-Enter': runIt, Tab: c => c.somethingSelected() ? c.indentSelection('add') : c.replaceSelection('    '), Esc: () => $('#run').focus() } });
      P.cm.getInputField().setAttribute('aria-label', LANG[ex.type] + ' код редакторы');
      let t = null; const cm = P.cm;
      cm.on('change', () => { clearTimeout(t); t = setTimeout(() => S.saveCode(r.id, cm.getValue()), 500); });
      setTimeout(() => P && P.cm && P.cm.refresh(), 0);
    } else {
      host.innerHTML = '<textarea id="plain" spellcheck="false" class="plain-ed"></textarea>';
      const ta = $('#plain'); ta.value = value;
      P.cm = { getValue: () => ta.value, setValue: v => { ta.value = v; }, refresh() {} };
    }
    $('#run').onclick = runIt;
    $('#check').onclick = doCheck;
    $('#reset').onclick = () => { P.cm.setValue(ex.starter || ''); $('#verdict').innerHTML = ''; };
    const R = ex.type === 'sql' ? null : DJ.run[ex.type === 'python' ? 'py' : ex.type];
    if (R && R.status === 'idle') R.start().catch(() => {});
  }
  function showHint() {
    const ex = P.ex, id = P.r.id;
    if (P.hints >= ex.hints.length) return;
    $('#hints').insertAdjacentHTML('beforeend', `<div class="hint"><b>Кеңес ${P.hints + 1}.</b> ${ex.hints[P.hints]}</div>`);
    P.hints++; if (S.markHinted) S.markHinted(id);
    const b = $('#hint-btn');
    if (P.hints >= ex.hints.length) { b.remove(); offerSolution(); } else b.textContent = `Тағы кеңес (${ex.hints.length - P.hints})`;
  }
  function offerSolution() {
    if ($('#sol-btn')) return;
    $('#sol-slot').innerHTML = '<button class="btn ghost" id="sol-btn">Шешімді көрсету</button>';
    $('#sol-btn').onclick = () => { if (S.markHinted) S.markHinted(P.r.id); P.cm.setValue(P.ex.solution); $('#sol-btn').remove(); $('#verdict').innerHTML = '<div class="verdict info">Шешім редакторға қойылды. Оны оқып, түсінгеннен кейін тексеріңіз. XP жартысы беріледі.</div>'; };
  }
  const tableHtml = r => !r ? '<p class="muted" style="margin:0">Сұрау кесте қайтармады.</p>'
    : `<div style="overflow-x:auto"><table><tr>${r.columns.map(c => `<th>${esc(c)}</th>`).join('')}</tr>${r.values.slice(0, 200).map(row => `<tr>${row.map(v => `<td>${v === null ? '<span class="muted">NULL</span>' : esc(v)}</td>`).join('')}</tr>`).join('')}</table></div>`;
  const busy = on => ['#run', '#check'].forEach(s => { const b = $(s); if (b) b.disabled = on; });
  async function runtime(ex) {
    const R = DJ.run[ex.type === 'python' ? 'py' : ex.type];
    if (R.status !== 'ready') $('#out').innerHTML = `<p class="muted" style="margin:0">${R.label ? `${R.label} компиляторы жүктелуде${R.size ? ', ' + R.size : ''}…` : 'Python ортасы жүктелуде. Бірінші рет біраз уақыт алады…'}</p>`;
    await R.start();
    return R;
  }
  async function doRun() {
    const me = P, ex = P.ex, code = P.cm.getValue(), stale = () => P !== me || !$('#out');
    busy(true); $('#verdict').innerHTML = '';
    try {
      if (ex.type === 'sql') {
        const r = await DJ.run.sql.run(code, ex.dataset);
        if (stale()) return;
        $('#out').innerHTML = !r.ok ? `<pre style="color:var(--bad)">${esc(r.error)}</pre>` : r.results.length ? r.results.map(tableHtml).join('') : `<p style="margin:0">Сұрау орындалды. Өзгерген жолдар: ${r.changes}.</p>`;
      } else {
        const R = await runtime(ex);
        if (stale()) return;
        $('#out').innerHTML = '<p class="muted" style="margin:0">Орындалуда…</p>';
        const r = await R.run(code, $('#stdin') ? $('#stdin').value : '');
        if (stale()) return;
        const err = r.error || r.stderr;
        $('#out').innerHTML = (r.stdout ? `<pre>${esc(r.stdout)}</pre>` : '') + (err ? `<pre style="color:var(--bad)">${esc(err)}</pre>` : '') || '<p class="muted" style="margin:0">Код орындалды, бірақ ештеңе шығармады.</p>';
      }
    } catch (e) { if (!stale()) $('#out').innerHTML = `<div class="verdict bad">${esc(e.message || e)}</div>`; }
    finally { if (!stale()) busy(false); }
  }
  async function doCheck() {
    const me = P, ex = P.ex, id = P.r.id, code = P.cm.getValue(), stale = () => P !== me || !$('#verdict');
    S.saveCode(id, code);
    busy(true); $('#verdict').innerHTML = '<div class="verdict info">Тексерілуде…</div>';
    let r;
    try {
      r = ex.type === 'sql' ? await DJ.run.sql.check(ex, code) : await (await runtime(ex)).check(ex, code);
      if (stale()) return;
      if (r.shown) $('#out').innerHTML = tableHtml(r.shown);
      else {
        let out = '';
        if (r.stdout) out += `<div class="eyebrow">Сіздің шығысыңыз</div><pre>${esc(r.stdout)}</pre>`;
        if (r.trace) out += `<pre style="color:var(--bad)">${esc(r.trace)}</pre>`;
        if (r.expected != null) out += `<div class="eyebrow" style="margin-top:10px">Күтілген шығыс</div><pre>${esc(r.expected)}</pre>`;
        $('#out').innerHTML = out || '<p class="muted" style="margin:0">Шығыс жоқ.</p>';
      }
    } catch (e) { if (!stale()) { busy(false); $('#verdict').innerHTML = `<div class="verdict bad">${esc(e.message || e)}</div>`; } return; }
    busy(false);
    if (!r.pass) {
      P.fails++;
      $('#verdict').innerHTML = `<div class="verdict bad">${r.msg || 'Әзірге дұрыс емес.'}</div>`;
      if (P.fails >= 3 && P.hints >= (ex.hints || []).length) offerSolution();
      return;
    }
    const res = S.complete(id, ex.xp || P.r.xp || 10, !!(S.hinted && S.hinted(id)), ex.type);
    track('problem_pass', { ex: id, type: ex.type, first: !!res.xp, guest: S.isGuest() });
    celebrate(res, $('#check')); topbar();
    if (res.daily) toast(`<b>Күн есебі шешілді!</b> +${res.daily} XP`, 'star', 'badge');
    const i = list.indexOf(P.r), p = S.progress();
    const nx = list.slice(i + 1).find(x => !p.done[x.id] && (!x.course || !P.r.course || x.course.id === P.r.course.id)) || list.find(x => !p.done[x.id]);
    $('#verdict').innerHTML = `<div class="verdict ok"><b>Дұрыс!</b>${res.xp ? ` <span class="xp-tag">+${res.xp} XP</span>` : ''}</div>`
      + (S.isGuest() && res.xp ? '<p class="guest-save">Прогресс жоғалмасын десеңіз, <button type="button" class="linkbtn" data-go="auth">тіркеліңіз</button>.</p>' : '')
      + (nx ? `<div class="actions" style="margin-top:10px"><button class="btn" id="p-next">Келесі есеп →</button><button class="btn ghost" data-go="problems">Тізімге</button></div>` : '');
    if (nx) $('#p-next').onclick = () => go('problem', { pid: nx.id });
  }

  // ================= self-exam on passed lessons =================
  function viewSelfTest() {
    $('#app').innerHTML = '<p class="muted" style="padding:40px 0" role="status">Жүктелуде…</p>';
    load().then(drawSelf).catch(() => { $('#app').innerHTML = '<p class="muted" style="padding:40px 0" role="alert">Жүктелмеді. Интернетті тексеріңіз.</p>'; });
  }
  function drawSelf() {
    if (ui.route.view !== 'selftest') return;
    const p = S.progress();
    // Passed lessons, grouped by module, with how many code tasks each has.
    const mods = [];
    for (const r of list) {
      const l = (DJ.modules[r.mod].lessons || [])[r.li];
      if (!l || !p.lessons[l.id]) continue;
      let m = mods.find(x => x.id === r.mod);
      if (!m) mods.push(m = { id: r.mod, mod: DJ.findModule(r.mod), lessons: [] });
      let e = m.lessons.find(x => x.id === l.id);
      if (!e) m.lessons.push(e = { id: l.id, title: r.title.replace(/ · \d+$/, ''), ltitle: l.title, ids: [] });
      e.ids.push(r.id);
    }
    const hist = (p.selfTests || []).slice(-5).reverse();
    if (!mods.length) {
      $('#app').innerHTML = `<div class="diag"><div class="card"><h1 style="margin:0 0 8px;font-size:1.5rem">Өзіңді тексер</h1>
        <p>Мұнда өткен тақырыптарыңыз бойынша кез келген уақытта өзіңізге емтихан аласыз. Әзірге код тапсырмасы бар бірде-бір сабақ аяқталмаған.</p>
        <div class="actions"><button class="btn" data-go="dash">Оқуды жалғастыру</button><button class="btn ghost" data-go="problems">Есептер</button></div></div></div>`;
      return;
    }
    $('#app').innerHTML = `<div class="diag self"><div class="card">
      <h1 style="margin:0 0 6px;font-size:1.6rem">Өзіңді тексер</h1>
      <p class="muted" style="margin:0 0 12px">Өткен тақырыптардан кездейсоқ есептер түседі. Кеңес пен шешім көрсетілмейді, таймер жүреді. Нәтиже тек өзіңізге көрінеді.</p>
      <form id="st-form">
        <fieldset class="st-mods"><legend>Тақырыптар</legend>
          ${mods.map(m => `<details ${mods.length < 3 ? 'open' : ''}><summary><label><input type="checkbox" data-mod-all="${m.id}" checked> <b>${esc(m.mod ? m.mod.code + ' ' + m.mod.title : m.id)}</b></label> <span class="note">${m.lessons.length} сабақ</span></summary>
            ${m.lessons.map(l => `<label class="st-l"><input type="checkbox" name="l" value="${esc(l.id)}" data-mod="${m.id}" checked> ${esc(l.ltitle)} <span class="note">${l.ids.length} есеп</span></label>`).join('')}</details>`).join('')}
        </fieldset>
        <div class="st-row"><label class="field">Есеп саны<select name="n">${[5, 10, 15, 20].map(n => `<option ${n === 10 ? 'selected' : ''}>${n}</option>`).join('')}</select></label>
          <label class="field">Уақыт<select name="min">${[[15, '15 мин'], [30, '30 мин'], [45, '45 мин'], [60, '60 мин'], [0, 'Шектеусіз']].map(([v, t]) => `<option value="${v}" ${v === 30 ? 'selected' : ''}>${t}</option>`).join('')}</select></label></div>
        <div class="actions"><button class="btn big" type="submit">Бастау ${ICON.play}</button></div>
        <div class="err" role="alert" id="st-err"></div>
      </form></div>
      ${hist.length ? `<div class="card" style="margin-top:14px"><h3 style="margin-top:0">Соңғы нәтижелер</h3>${hist.map(h => `<div class="st-h"><span>${esc(h.d)}</span><b>${h.ok} / ${h.n}</b><span class="note">${h.min ? h.min + ' мин' : 'шектеусіз'} · ${Math.round(h.ok / h.n * 100)}%</span></div>`).join('')}</div>` : ''}
    </div>`;
    $$('[data-mod-all]').forEach(c => c.onchange = () => $$(`input[data-mod="${c.dataset.modAll}"]`).forEach(x => { x.checked = c.checked; }));
    $$('input[name=l]').forEach(x => x.onchange = () => { const all = $(`[data-mod-all="${x.dataset.mod}"]`), sib = $$(`input[data-mod="${x.dataset.mod}"]`); all.checked = sib.every(s => s.checked); all.indeterminate = !all.checked && sib.some(s => s.checked); });
    $$('summary label').forEach(l => l.onclick = e => e.stopPropagation());
    $('#st-form').onsubmit = e => {
      e.preventDefault();
      const chosen = new Set($$('input[name=l]:checked').map(x => x.value));
      const pool = []; mods.forEach(m => m.lessons.forEach(l => { if (chosen.has(l.id)) pool.push(...l.ids); }));
      if (!pool.length) { $('#st-err').textContent = 'Кемінде бір тақырып таңдаңыз.'; return; }
      const n = Math.min(Number(e.target.n.value), pool.length), min = Number(e.target.min.value);
      for (let i = pool.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [pool[i], pool[j]] = [pool[j], pool[i]]; }
      track('selftest_start', { n, min });
      ui.startSelf({ tasks: pool.slice(0, n), minutes: min, title: 'Өзіңді тексер', lessons: chosen.size });
    };
  }

  return { viewProblems, viewProblem, viewSelfTest, leave() { P = null; } };
  };
})();
